```c
/*
 * The number of directory levels needed to store all blocks of
 * an export of the given size. With no directory levels at all
 * the block files live in the root of the tree, which can hold
 * TREEDIRSIZE of them; each extra level multiplies the capacity
 * by TREEDIRSIZE.
 */
static int tree_depth(off_t size) {
	off_t blocks = TREE_BLOCKS(size);
	off_t capacity = TREEDIRSIZE;
	int depth = 0;

	while (capacity < blocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}

	return depth;
}
