/**
 * Read from an export stored in a tree of files. Reads are
 * limited to the block containing the offset, so a single
 * request may need several calls.
 *
 * @param a offset in the export to start reading
 * @param buf buffer to read into
 * @param len size of the buffer
 * @param client client we're reading for
 * @return number of bytes read, or -1 on error
 **/
ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	char path[PATH_MAX];
	off_t ppos;
	off_t size = client->exportsize;
	ssize_t retval;
