/*
 * Tree files support.
 *
 * An export using the treefiles option is not stored in a single
 * (large) file. Instead, the exported device is divided into blocks
 * of TREEPAGESIZE bytes, each of which is stored in its own file.
 * The block files are spread over a tree of directories below the
 * export name, with at most TREEDIRSIZE files or subdirectories per
 * directory, so that neither the files nor the directories ever grow
 * very large. This is useful on filesystems that do not handle large
 * files well, such as fuse/ftpfs, davfs or other network filesystems.
 *
 * A block that has never been written has no file and reads as all
 * zeroes. Block files are created automatically when the block is
 * first written, and are deleted again when the block is trimmed.
 */

#include "config.h"
#include "lfs.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

#include "backend.h"
#include "cliserv.h"
#include "nbdsrv.h"
#include "nbd-debug.h"
#include "treefiles.h"

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/**
 * The number of directory levels needed to store an export of the
 * given size. Without any directory levels, the block files live
 * directly in the root of the tree, which can hold TREEDIRSIZE of
 * them; each extra level multiplies that capacity by TREEDIRSIZE.
 **/
static int tree_depth(off_t size) {
	off_t blocks = (size + TREEPAGESIZE - 1) / TREEPAGESIZE;
	off_t capacity = TREEDIRSIZE;
	int depth = 0;

	while (capacity < blocks) {
		depth++;
		capacity *= TREEDIRSIZE;
	}

	return depth;
}

/**
 * Construct the path of the block file holding a given position.
 *
 * @param name the name of the export (i.e., the root of the tree)
 * on input; the full path of the block file on output
 * @param lenmax the size of the buffer name points at
 * @param size the size of the export
 * @param pos a position in the export
 * @param ppos if not NULL, receives the offset within the block
 * file at which the position is found
 **/
void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos) {
	int idx[8];
	char *p;
	off_t b;
	int left;
	int depth;
	int used;
	int i;

	left = lenmax - strlen(name);
	if (left <= 0) {
		err("Path to tree file too long");
	}
	p = name + strlen(name);

	if (ppos) {
		*ppos = pos % TREEPAGESIZE;
	}

	/*
	 * Decompose the block number in base TREEDIRSIZE; idx[0] is
	 * the number of the block file, the other entries (if any)
	 * are the numbers of the directories leading to it.
	 */
	depth = tree_depth(size);
	b = pos / TREEPAGESIZE;
	for (i = 0; i <= depth; i++) {
		idx[i] = b % TREEDIRSIZE;
		b /= TREEDIRSIZE;
	}

	for (i = depth; i > 0; i--) {
		used = snprintf(p, left, "/TREE%04d", idx[i]);
		if (used < 0 || used >= left) {
			err("Path to tree file too long");
		}
		p += used;
		left -= used;
	}
	used = snprintf(p, left, "/FILE%04d", idx[0]);
	if (used < 0 || used >= left) {
		err("Path to tree file too long");
	}
}

/**
 * Create all directories of a path. Existing directories are
 * silently skipped. To create the parent directories of a file,
 * pass only the directory part of the file's path.
 *
 * @param path the path to create; temporarily modified
 **/
void mkdir_path(char *path) {
	char *p = path;

	while ((p = strchr(p + 1, '/')) != NULL) {
		*p = '\0';
		if (mkdir(path, 0700) < 0 && errno != EEXIST) {
			msg(LOG_ERR, "Could not create directory %s: %s",
					path, strerror(errno));
		}
		*p = '/';
	}
	if (mkdir(path, 0700) < 0 && errno != EEXIST) {
		msg(LOG_ERR, "Could not create directory %s: %s",
				path, strerror(errno));
	}
}

/**
 * Open the block file holding a given position, creating the file
 * (and any missing directories) if it does not exist yet.
 *
 * @param name the name of the export (i.e., the root of the tree)
 * @param mode open mode, as for open(2)
 * @param size the size of the export
 * @param pos a position in the export
 * @param mutex lock serializing file creation, or NULL
 * @return a file descriptor, or -1 on failure
 **/
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex) {
	char path[PATH_MAX];
	char *p;
	int fd;

	snprintf(path, sizeof path, "%s", name);
	construct_path(path, sizeof path, size, pos, NULL);

	if (mutex) {
		pthread_mutex_lock(mutex);
	}
	if ((p = strrchr(path, '/')) != NULL && p != path) {
		*p = '\0';
		mkdir_path(path);
		*p = '/';
	}
	fd = open(path, mode | O_CREAT, 0600);
	if (mutex) {
		pthread_mutex_unlock(mutex);
	}
	if (fd < 0) {
		msg(LOG_ERR, "Could not open tree file %s: %s",
				path, strerror(errno));
	}

	return fd;
}

/**
 * Delete the block file holding a given position, if it exists.
 *
 * @param name the name of the export (i.e., the root of the tree)
 * @param size the size of the export
 * @param pos a position in the export
 **/
void delete_treefile(char *name, off_t size, off_t pos) {
	char path[PATH_MAX];

	snprintf(path, sizeof path, "%s", name);
	construct_path(path, sizeof path, size, pos, NULL);
	if (unlink(path) < 0 && errno != ENOENT) {
		msg(LOG_ERR, "Could not delete tree file %s: %s",
				path, strerror(errno));
	}
}

/**
 * Read from an export stored in a tree of files. The read is
 * limited to the block containing the offset, so satisfying a
 * single request may take several calls.
 *
 * @param a the offset where the read should start
 * @param buf a buffer to read into
 * @param len the size of buf
 * @param client the client we're reading for
 * @return the number of bytes read, or -1 on error
 **/
ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	char path[PATH_MAX];
	off_t ppos;
	ssize_t retval;
	int fd;

	snprintf(path, sizeof path, "%s", client->exportname);
	construct_path(path, sizeof path, client->exportsize, a, &ppos);
	if (len > (size_t)(TREEPAGESIZE - ppos)) {
		len = TREEPAGESIZE - ppos;
	}

	DEBUG("(TREE READ from %s offset %llu len %u), ", path,
			(long long unsigned)ppos, (unsigned int)len);

	fd = open(path, O_RDONLY);
	if (fd < 0) {
		if (errno == ENOENT) {
			/* Blocks that were never written read as zeroes */
			memset(buf, 0, len);
			return len;
		}
		msg(LOG_ERR, "Could not open tree file %s: %s",
				path, strerror(errno));
		return -1;
	}
	retval = pread(fd, buf, len, ppos);
	if (retval == 0) {
		/* Reading past the end of a block file yields zeroes */
		memset(buf, 0, len);
		retval = len;
	}
	close(fd);

	return retval;
}

/**
 * Write to an export stored in a tree of files. The write is
 * limited to the block containing the offset, so satisfying a
 * single request may take several calls.
 *
 * @param a the offset where the write should start
 * @param buf the buffer to write from
 * @param len the length of buf
 * @param client the client we're writing for
 * @param fua flag to indicate 'Force Unit Access'
 * @return the number of bytes written, or -1 on error
 **/
ssize_t treeexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	off_t ppos = a % TREEPAGESIZE;
	ssize_t retval;
	int fd;

	if (len > (size_t)(TREEPAGESIZE - ppos)) {
		len = TREEPAGESIZE - ppos;
	}

	fd = open_treefile(client->exportname, O_WRONLY,
			client->exportsize, a, &client->treemutex);
	if (fd < 0) {
		return -1;
	}

	DEBUG("(TREE WRITE to %s.%lld offset %llu len %u fua %d), ",
			client->exportname, (long long)(a / TREEPAGESIZE),
			(long long unsigned)ppos, (unsigned int)len, fua);

	retval = pwrite(fd, buf, len, ppos);
	if (retval > 0) {
		if (client->server->flags & F_SYNC) {
			fsync(fd);
		} else if (fua) {
			fdatasync(fd);
		}
	}
	close(fd);

	return retval;
}

/**
 * Trim an export stored in a tree of files. Blocks that are
 * covered by the trim in their entirety lose their file (and
 * will hence read as zeroes again); for partially covered
 * blocks, a hole is punched into the file instead.
 *
 * @param a the offset where the trim should start
 * @param len the number of bytes to trim
 * @param client the client we're trimming for
 * @return 0 on success, -1 on failure
 **/
int treeexptrim(off_t a, size_t len, CLIENT *client) {
	char path[PATH_MAX];
	off_t ppos;
	size_t clen;
	int fd;

	while (len > 0) {
		ppos = a % TREEPAGESIZE;
		clen = TREEPAGESIZE - ppos;
		if (clen > len) {
			clen = len;
		}
		if (ppos == 0 && clen == TREEPAGESIZE) {
			delete_treefile(client->exportname,
					client->exportsize, a);
		} else {
			snprintf(path, sizeof path, "%s", client->exportname);
			construct_path(path, sizeof path,
					client->exportsize, a, NULL);
			fd = open(path, O_RDWR);
			if (fd >= 0) {
				punch_hole(fd, ppos, clen);
				close(fd);
			} else if (errno != ENOENT) {
				msg(LOG_ERR, "Could not open tree file %s: %s",
						path, strerror(errno));
				return -1;
			}
		}
		a += clen;
		len -= clen;
	}

	return 0;
}

#ifndef NBD_TREEFILES_H
#define NBD_TREEFILES_H

#include <pthread.h>
#include <sys/types.h>

#include "nbdsrv.h"

#define TREEDIRSIZE  1024 /**< number of files per subdirectory (or subdirs per subdirectory) */
#define TREEPAGESIZE 4096 /**< tree (block) files uses those chunks */

void construct_path(char *name, int lenmax, off_t size, off_t pos, off_t *ppos);
void delete_treefile(char *name, off_t size, off_t pos);
void mkdir_path(char *path);
int open_treefile(char *name, mode_t mode, off_t size, off_t pos, pthread_mutex_t *mutex);
ssize_t treeexpread(off_t a, char *buf, size_t len, CLIENT *client);
ssize_t treeexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua);
int treeexptrim(off_t a, size_t len, CLIENT *client);

#endif

