/**
 * Set up a treefiles export. The data of such an export lives in a
 * tree of TREEPAGESIZE-byte files below a directory named after the
 * export; files (and directories) are opened and created on demand,
 * so no file handles are set up here.
 *
 * @param client information on the client which we want to setup export for
 * @return true on success, false on failure
 **/
static bool setupexport_treefiles(CLIENT* client) {
	struct stat st;

	if(!(client->server->expected_size)) {
		err_nonfatal("treefiles export requires the filesize option to be set");
		return false;
	}
	client->export = NULL;
	client->exportsize = client->server->expected_size;

	if (stat(client->exportname, &st) == 0) {
		if (!S_ISDIR(st.st_mode)) {
			err_nonfatal("treefiles export needs a directory, but the exportname is not one");
			return false;
		}
		return true;
	}
	if (client->server->flags & F_READONLY) {
		/* The tree does not exist yet, so everything reads
		 * as zeroes */
		return true;
	}
	mkdir_path(client->exportname);
	if (stat(client->exportname, &st) < 0 || !S_ISDIR(st.st_mode)) {
		err_nonfatal("Could not create directory tree for treefiles export: %m");
		return false;
	}

	return true;
}

